// Calcula las alertas de reposición a partir de seed.sql (repositorio del proyecto).
// Replica la Consulta 2 de consultas_analiticas.sql:
//   WHERE stock_minimo IS NOT NULL AND stock_actual < stock_minimo
//   ORDER BY unidades_a_reponer DESC
const sql = $input.first().json.data;

// Lee los valores de un INSERT ... VALUES(...): textos entre comillas, números o NULL
function leerValores(s) {
  const out = [];
  let i = 0;
  while (i < s.length) {
    while (s[i] === ' ' || s[i] === ',') i++;
    if (i >= s.length) break;
    if (s[i] === "'") {
      let v = '';
      i++;
      while (i < s.length) {
        if (s[i] === "'") {
          if (s[i + 1] === "'") { v += "'"; i += 2; continue; } // comilla escapada
          i++;
          break;
        }
        v += s[i++];
      }
      out.push(v);
    } else {
      let j = i;
      while (j < s.length && s[j] !== ',') j++;
      const t = s.slice(i, j).trim();
      out.push(t === 'NULL' ? null : Number(t));
      i = j;
    }
  }
  return out;
}

const filas = { categoria: [], producto: [], inventario: [] };
const re = /^INSERT INTO (categoria|producto|inventario) VALUES\((.*)\);\s*$/gm;
let m;
while ((m = re.exec(sql)) !== null) filas[m[1]].push(leerValores(m[2]));

const categorias = Object.fromEntries(filas.categoria.map(([id, nombre]) => [id, nombre]));
const productos = Object.fromEntries(filas.producto.map(([sku, nombre, idCat]) => [sku, { nombre, categoria: categorias[idCat] }]));

// inventario: (id_registro, sku, stock_actual, stock_minimo, fecha_actualizacion, comentario)
const alertas = filas.inventario
  .filter(([, , actual, minimo]) => minimo !== null && actual < minimo)
  .map(([, sku, actual, minimo]) => ({
    codigo: sku,
    nombre: productos[sku].nombre,
    categoria: productos[sku].categoria,
    stock_actual: actual,
    stock_minimo: minimo,
    deficit: minimo - actual,
  }))
  .sort((a, b) => b.deficit - a.deficit);

// Contexto adicional para el correo (mismas definiciones que Consultas 1 y 5)
const agotados = filas.inventario.filter(([, , actual]) => actual === 0).length;
const criticosSinUmbral = filas.inventario.filter(([, , actual, minimo]) => minimo === null && actual >= 1 && actual <= 2).length;

const fecha = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const deficitTotal = alertas.reduce((s, a) => s + a.deficit, 0);

const tabla = alertas.map(p =>
  `<tr><td>${p.codigo}</td><td>${p.nombre}</td><td>${p.categoria}</td>` +
  `<td style="text-align:right">${p.stock_actual}</td>` +
  `<td style="text-align:right">${p.stock_minimo}</td>` +
  `<td style="text-align:right"><b>${p.deficit}</b></td></tr>`).join('');

const html =
  `<p>Hola Alejandro,</p>` +
  `<p>El sistema de inventario detectó <b>${alertas.length}</b> producto(s) bajo su stock mínimo ` +
  `(revisión del ${fecha}). Se necesitan <b>${deficitTotal}</b> unidades para recuperar los mínimos.</p>` +
  `<table border="1" cellpadding="4" cellspacing="0">` +
  `<tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Stock</th><th>Mínimo</th><th>Déficit</th></tr>` +
  tabla + `</table>` +
  `<p>Ordenados por déficit: los primeros son los más urgentes de reponer.</p>` +
  `<p><i>Contexto: ${agotados} de ${filas.inventario.length} productos están agotados y ` +
  `${criticosSinUmbral} tienen 1 o 2 unidades sin stock mínimo definido.</i></p>` +
  `<p>— Sistema de Inventario Eliko</p>`;

return [{ json: {
  fecha_consulta: fecha,
  total_productos: filas.producto.length,
  total_categorias: filas.categoria.length,
  total_alertas: alertas.length,
  deficit_total: deficitTotal,
  productos_agotados: agotados,
  criticos_sin_umbral: criticosSinUmbral,
  productos: alertas,
  asunto: `[Eliko] ${alertas.length} producto(s) bajo stock mínimo`,
  html,
}}];
